 probes=[(50,70,(51,102,153)),(130,110,(51,179,102)),(190,160,(51,179,102)),(350,100,(179,128,51)),(430,100,(128,77,204)),(600,360,(10,13,18))]
 for x,y,want in probes:
  actual=im.getpixel((x*2,y*2));assert all(abs(a-b)<=1 for a,b in zip(actual,want)),(x,y,actual,want)
 hull=sum(im.getpixel((x,y))==(255,128,51) for y in range(418,592) for x in range(958,1132))
 curve=sum(im.getpixel((x,y))==(77,204,255) for y in range(540,660) for x in range(78,483))
